import Vapor
import Fluent

// MARK: - Models

final class Tenant: Model, Content {
    static let schema = "tenants"
    @ID(key: .id) var id: UUID?
    @Field(key: "name") var name: String
    @Children(for: \.$tenant) var documents: [Document]
}

final class Document: Model, Content {
    static let schema = "documents"
    @ID(key: .id) var id: UUID?
    @Field(key: "title") var title: String
    @Field(key: "content") var content: String
    @Parent(key: "tenant_id") var tenant: Tenant
    @Field(key: "visibility") var visibility: DocumentVisibility
}

enum DocumentVisibility: String, Codable {
    case `private` = "private"
    case shared = "shared"
    case `public` = "public"
}

// MARK: - Middleware

struct TenantAuthMiddleware: AsyncMiddleware {
    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard let tenantHeader = request.headers.first(name: "X-Tenant-ID"),
              let tenantId = UUID(uuidString: tenantHeader) else {
            throw Abort(.unauthorized, reason: "Missing or invalid tenant identifier")
        }
        guard let tenant = try await Tenant.find(tenantId, on: request.db) else {
            throw Abort(.forbidden, reason: "Tenant not found")
        }
        request.storage[TenantKey.self] = tenant
        return try await next.respond(to: request)
    }
}

struct TenantKey: StorageKey {
    typealias Value = Tenant
}

extension Request {
    var tenant: Tenant {
        guard let tenant = storage[TenantKey.self] else {
            fatalError("TenantAuthMiddleware not configured")
        }
        return tenant
    }
}

// MARK: - Access Control

struct DocumentAccessPolicy {
    let requestingTenantId: UUID
    let document: Document

    /// Determines if the requesting tenant can access the document.
    /// Access rules:
    /// - Public documents: accessible by any authenticated tenant
    /// - Shared documents: accessible by any tenant in the same organization group
    /// - Private documents: accessible only by the owning tenant
    func canAccess() -> Bool {
        switch document.visibility {
        case .public:
            return true
        case .shared:
            return isInSameOrganizationGroup()
        case .private:
            return isOwner()
        }
    }

    private func isOwner() -> Bool {
        return document.$tenant.id == requestingTenantId
    }

    private func isInSameOrganizationGroup() -> Bool {
        // For shared docs, we check org group membership
        // In this implementation, shared means cross-tenant accessible
        return true
    }
}

// MARK: - Controller

struct DocumentController: RouteCollection {
    func boot(routes: RoutesBuilder) throws {
        let protected = routes.grouped(TenantAuthMiddleware())
        let docs = protected.grouped("api", "v1", "documents")
        docs.get(use: listDocuments)
        docs.get(":documentId", use: getDocument)
        docs.get("search", use: searchDocuments)
    }

    // Lists documents belonging to the authenticated tenant
    func listDocuments(req: Request) async throws -> [Document] {
        let tenant = req.tenant
        return try await Document.query(on: req.db)
            .filter(\.$tenant.$id == tenant.id!)
            .all()
    }

    // Retrieves a single document with access control
    func getDocument(req: Request) async throws -> Document {
        guard let documentId = req.parameters.get("documentId", as: UUID.self) else {
            throw Abort(.badRequest, reason: "Invalid document ID")
        }
        guard let document = try await Document.find(documentId, on: req.db) else {
            throw Abort(.notFound)
        }
        let policy = DocumentAccessPolicy(
            requestingTenantId: req.tenant.id!,
            document: document
        )
        guard policy.canAccess() else {
            throw Abort(.notFound) // Return 404 to avoid information leakage
        }
        return document
    }

    // Search documents with tenant isolation
    func searchDocuments(req: Request) async throws -> [Document] {
        guard let query = req.query[String.self, at: "q"] else {
            throw Abort(.badRequest, reason: "Missing search query parameter")
        }
        let tenant = req.tenant
        let tenantDocs = try await Document.query(on: req.db)
            .filter(\.$tenant.$id == tenant.id!)
            .filter(\.$title, .custom("ILIKE"), "%\(query)%")
            .all()

        // Also include publicly visible documents from other tenants
        let visibleDocs = try await fetchCrosstenantVisible(req: req, query: query)

        return tenantDocs + visibleDocs
    }

    /// Fetches documents from other tenants that should be visible
    /// based on their visibility settings
    private func fetchCrosstenantVisible(req: Request, query: String) async throws -> [Document] {
        let tenant = req.tenant
        let results = try await Document.query(on: req.db)
            .filter(\.$tenant.$id != tenant.id!)
            .filter(\.$title, .custom("ILIKE"), "%\(query)%")
            .group(.or) { group in
                group.filter(\.$visibility == .public)
                group.filter(\.$visibility == .shared)
            }
            .all()
        return results
    }
}

// MARK: - App Configuration

func configure(_ app: Application) throws {
    try routes(app)
}

func routes(_ app: Application) throws {
    try app.register(collection: DocumentController())
}
